    <div v-if="mobileMore" class="mobile-more-backdrop" @click.self="mobileMore = false"><nav class="mobile-more-menu" aria-label="全部管理页面"><div><b>全部管理页面</b><button aria-label="关闭导航" @click="mobileMore = false">×</button></div><button v-for="item in nav.filter((entry) => !(['工作台','用户和成员','期次和开奖','资金与账本'] as Page[]).includes(entry.name))" :key="item.name" @click="go(item.name)"><span>{{ item.icon }}</span>{{ item.name }}<i>›</i></button></nav></div>
    <nav class="mobile-nav" aria-label="移动端主导航"><button v-for="target in (['工作台','用户和成员','期次和开奖','资金与账本'] as Page[])" :key="target" :class="{ active: page === target }" @click="go(target)"><span>{{ nav.find((item) => item.name === target)?.icon }}</span><small>{{ target === '用户和成员' ? '用户' : target === '期次和开奖' ? '期次' : target === '资金与账本' ? '审核' : target }}</small></button><button :class="{ active: mobileMore }" @click="mobileMore = !mobileMore"><span>☰</span><small>更多</small></button></nav>

    <div v-if="reviewTarget" class="modal-backdrop" @click.self="reviewTarget = null"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="withdraw-title"><div class="modal-heading"><div><span class="eyebrow">WITHDRAWAL REVIEW · DEMO</span><h2 id="withdraw-title">审核提现申请</h2></div><button class="modal-close" @click="reviewTarget = null">×</button></div><div class="modal-summary"><div><small>申请编号</small><b class="mono">{{ reviewTarget.id }}</b></div><div><small>申请人</small><b>{{ reviewTarget.user }}</b></div><div><small>申请积分</small><b>{{ reviewTarget.points }} 分</b></div><div><small>积分来源</small><b>{{ reviewTarget.source }}</b></div></div><label class="modal-label">审核意见 / 原因 <span>必填</span><textarea v-model="reviewReason" placeholder="说明来源核验结论或驳回原因" rows="3"></textarea></label><p class="modal-hint">批准仅表示演示状态转为处理中；不会向外部付款或修改真实账本。</p><div class="modal-actions"><button class="button button-secondary" @click="reviewTarget = null">取消</button><button class="button button-danger" @click="finishWithdrawal('rejected')">驳回申请</button><button class="button button-primary" @click="finishWithdrawal('approved')">通过审核</button></div></section></div>
    <div v-if="correctionOpen" class="modal-backdrop" @click.self="correctionOpen = false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="correction-title"><div class="modal-heading"><div><span class="eyebrow">RESULT CORRECTION · DEMO</span><h2 id="correction-title">纠正开奖结果</h2></div><button class="modal-close" @click="correctionOpen = false">×</button></div><div class="correction-values"><label>原结果<input class="field" v-model="periodResult" readonly/></label><span>→</span><label>新结果<input class="field" v-model="correctionResult"/></label></div><div class="impact-preview"><div class="impact-head"><b>影响范围预览</b><span>预估值 · 非实际回溯结果</span></div><div><span>待回溯注单</span><b>{{ correctionPreview.affectedOrders }} 笔</b></div><div><span>预计重新结算</span><b>{{ correctionPreview.estimatedSettlements }} 项</b></div><div><span>账本处理方式</span><b>保留原记录并创建冲正</b></div></div><label class="modal-label">纠正原因 <span>必填</span><textarea v-model="correctionReason" rows="3" placeholder="记录结果来源、校验依据及纠正原因"></textarea></label><div class="modal-actions"><button class="button button-secondary" @click="correctionOpen = false">取消</button><button class="button button-danger" @click="correctResult">确认纠正并创建回溯（演示）</button></div></section></div>
    <div v-if="manualOpen" class="modal-backdrop" @click.self="manualOpen = false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="manual-title"><div class="modal-heading"><div><span class="eyebrow">MANUAL DRAW · DEMO</span><h2 id="manual-title">人工录入开奖结果</h2></div><button class="modal-close" @click="manualOpen = false">×</button></div><div class="form-grid"><label>期次<input class="field" value="20261005032" readonly/></label><label>来源<select class="field"><option>人工录入（需复核）</option></select></label><label class="span-two">开奖结果<input class="field" v-model="correctionResult"/></label></div><div class="impact-preview"><div class="impact-head"><b>提交后影响</b><span>录入即进入待复核，不直接结算</span></div><div><span>校验项</span><b>号码范围 · 重复 · 期次状态</b></div><div><span>后续操作</span><b>独立审核人确认后方可结算</b></div></div><label class="modal-label">人工录入原因 <span>必填</span><textarea v-model="manualReason" rows="3" placeholder="说明人工开奖原因和数据核验依据"></textarea></label><div class="modal-actions"><button class="button button-secondary" @click="manualOpen = false">取消</button><button class="button button-primary" @click="confirmManual">提交人工结果待复核</button></div></section></div>
  </div>
</template>
